"""Seed data for the shared personnel register: specializations, functional departments, ranks, personality vocab,
and the identities of the agents that already exist in code.

Departments are FUNCTIONAL — never by race. Specializations are not locked to a race. Rank, race and personality grant
no permission. `tools` on a specialization lists real Tool Gateway tools as *suggestions*; access is a governed grant.
"""
from __future__ import annotations

from typing import Any

RANKS = ["Junior Agent", "Specialist", "Senior Specialist", "Team Lead", "Department Lead", "Advisor", "Council Member",
         "Custom"]
SKILL_LEVELS = ["Beginner", "Intermediate", "Advanced", "Expert", "Unverified"]
SKILL_BASIS = ["assigned", "tested", "measured"]  # assigned ≠ tested ≠ measured performance — never conflated
TRAITS = ["Mischievous", "Curious", "Loyal", "Analytical", "Competitive", "Cautious", "Chaotic", "Meticulous", "Sarcastic",
          "Creative", "Secretive", "Playful", "Stoic", "Dramatic", "Ambitious", "Patient", "Stubborn", "Protective",
          "Observant", "Resourceful", "Diplomatic", "Ruthless in fictional tone", "Humorous", "Calm", "Energetic"]
COMM_STYLES = ["Formal", "Casual", "Technical", "Concise", "Detailed", "Humorous", "Sarcastic", "Diplomatic", "Direct",
               "Analytical", "Creative", "Storytelling"]
LANGUAGES = ["English", "Swedish"]  # what the UI and prompts are actually written for; others are model-dependent
LIFECYCLE = ["DRAFT", "PENDING_REVIEW", "APPROVAL_REQUIRED", "READY", "INITIALIZING", "ACTIVE", "PAUSED", "DISABLED",
             "ARCHIVED", "FAILED"]
SOURCES = ["CODE", "GSUS_CHAT", "BESTIARY", "PERSONNEL", "API", "ADMIN"]
RELATIONSHIP_TYPES = ["collaborates", "mentors", "rivalry", "friendship", "challenges"]
TRACE_WARNING = "Du kan gömma dig i vilken dimension du vill. Din task trace följer med."


def _sp(key: str, name: str, description: str, competencies: list[str], tools: list[str], departments: list[str],
        tasks: list[str], keywords: list[str]) -> dict[str, Any]:
    return {"key": key, "name": name, "description": description, "competencies": competencies, "tools": tools,
            "departments": departments, "example_tasks": tasks, "keywords": keywords}


